/* Data Flow: Split Inventory | Mutate - Create Inventory */

$state.context.(
  /* This assumes the grossWeight and netWeight units are the same! */
  /* For know we are going to base the weight on the qty. Until we have tare weights from packaging this wont matter */
  $tareWeight := $coalesce([oldSource.grossWeight.value - oldSource.netWeight.value, 0]);
  $quantityRatio := input.splitQty / oldSource.quantity.value;
  $reverseQuantityRatio := (1 - $quantityRatio);

  {
    "sourcePayload": INFO.oldSource.{
      "update": {
        "quantity": {
          "value": quantity.value - $state.context.INPUT.splitQty
        },
        "grossWeight": $isNotNilOrEmpty(grossWeight) and $isNotNilOrEmpty(netWeight) ? {
          "value": (quantity.value - $state.context.INPUT.splitQty)*product.weight.value,
          "unitId": grossWeight.unitId
        },
        "netWeight": $isNotNilOrEmpty(netWeight) ? {
          "value": (quantity.value - $state.context.INPUT.splitQty)*product.weight.value,
          "unitId": netWeight.unitId
        },
        "lastTransactionTypeId": "inventorySplit",
        "inventoryStatusId": quantity.value - $state.context.INPUT.splitQty = 0? "retired",
        "active": quantity.value - $state.context.INPUT.splitQty = 0? false
      },
      "where": {
        "id": id
      }
    },

    "destinationPayload": {
      "create": INFO.oldSource ~> | $ | $state.context.INFO.oldSource.(
        {
          "quantity": {
            "value": $state.context.INPUT.splitQty,
            "unitId": quantity.unitId
          },
          "grossWeight": $isNotNilOrEmpty(grossWeight) and $isNotNilOrEmpty(netWeight) ? {
            /* This assumes the grossWeight and netWeight units are the same! */
            "value": $state.context.INPUT.splitQty*product.weight.value,
            "unitId": $exists(grossWeight.unitId) ? grossWeight.unitId : null
          },
          "netWeight": $isNotNilOrEmpty(netWeight) ? {
            "value":  $state.context.INPUT.splitQty*product.weight.value,
            "unitId": netWeight.unitId
          },
          "handlingUnitId": null, /* Inventory cannot share handling unit once split (to help differentiate them, may be added later) */
          "barcode": null, /* Cannot have same barcode (serialNumber is unique identifier for now, barcode can optionally be added later) */
          "lastTransactionTypeId": "inventorySplit"
        }
      ), [ /* Remove id and serial number so they can be auto-generated unique from oldSource */
        "id",
        "serialNumber",
        "packagingConfiguration", /* Remove the object, the id was already queried */
        "inventoryStatus",
        "product"
      ] |
    }
  }
)

data.mutation:
mutation SplitInventory(
  $sourcePayload: [InventoryUpdatePayloadInput!]!,
  $destinationPayload: [InventoryCreatePayloadInput!]!) {

  newSource: updateInventory(payload: $sourcePayload) {
    id
    quantity { value unitId }
  }

  newDestination: createInventory(payload: $destinationPayload) {
    id
    serialNumber
    quantity { value unitId }
  }
}

data.query:
query QueryInventory($inventoryId: String!) {
  oldSource: inventory(
    where: { id: { _eq: $inventoryId } },
    readPreference: primaryPreferred
  ) {
    edges {
      node {
        id
        active
        serialNumber
        quantity { value unitId }
        shippable
        barcode
        trackingNumber
        note
        grossWeight { value unitId }
        netWeight { value unitId }
        expiresAt
        lastCountAt
        manufacturedAt
        workOrderId
        externalId
        extProductId
        extProcessId
        customData
        integrationData
        handlingUnitId
        inventoryStatusId
        inventoryStatus { code }
        lastTransactionTypeId
        storageUnitId
        lastAdjustmentId
        lotId
        processId
        productId
        product{
          weight{ value unitId}
        }
        receiptLineId
      }
    }
  }
}

