  "success": false,
  "message": "Entered split quantity of " & $state.context.INPUT.splitQty & " cannot be 0 or negative"
}

$state.context.({
  "success": false,
  "message": "Units for this inventory's gross and net weight are different. Unable to compute new weights.",
  "data": INFO.oldSource.{
    "Net Weight Units": netWeight.unitId,
    "Gross Weight Units": grossWeight.unitId
  }
})

